<?php
/**  Code Snippets - Admin UI (hooks the admin hook, as every enabled plugin must). */
if (empty($GLOBALS['adminarea'])) return;
add_menu_item('dashboard', ['name'=>'nexa-snippets','class'=>(($_GET['plugin_page']??'')==='nexa-snippets')?'active':'','icon'=>'fa fa-code fa-fw','label'=>' Code Snippets','link'=>'admin.php?plugin_page=nexa-snippets'], 58);
add_action('nexa_admin','nexa_snippets_admin_render'); add_action('di_admin','nexa_snippets_admin_render'); add_action('up_admin','nexa_snippets_admin_render');
function nexa_snippets_admin_render(): void { static $done=false; if($done) return; if(($_GET['plugin_page']??'')!=='nexa-snippets') return; $done=true;
    nexa_snippets_ensure();
    if(($_SERVER['REQUEST_METHOD']??'')==='POST' && nexa_verify_csrf()){ if(($_POST['do']??'')==='del') query("DELETE FROM snippets WHERE id=?",[(int)$_POST['id']]); elseif(($_POST['do']??'')==='toggle') query("UPDATE snippets SET active=? WHERE id=?",[(string)$_POST['active'],(int)$_POST['id']]); else query("INSERT INTO snippets (name,location,code,active,created_at) VALUES (?,?,?,?,?)",[trim((string)$_POST['name']),(string)$_POST['location'],(string)$_POST['code'],'1',date('Y-m-d H:i:s')]); echo '<div class="alert alert-success">Snippets updated.</div>'; }
    echo '<h2><i class="fa fa-code"></i> Code Snippets</h2><div class="alert alert-warning">Only paste code you trust - snippets are output as-is. Admins only.</div><form method="post">'.nexa_csrf_field().'<div class="form-group"><input name="name" required class="form-control" placeholder="Snippet name"></div><div class="form-group"><select name="location" class="form-control"><option value="head">Head</option><option value="footer">Footer (post)</option></select></div><div class="form-group"><textarea name="code" rows="4" class="form-control" placeholder="<script>...</script>"></textarea></div><button class="btn btn-primary">Add Snippet</button></form><hr><table class="table table-striped"><thead><tr><th>Name</th><th>Location</th><th>Active</th><th></th></tr></thead><tbody>';
    foreach(query("SELECT * FROM snippets ORDER BY id DESC") as $r) echo '<tr><td>'.esc_html($r['name']).'</td><td>'.esc_html($r['location']).'</td><td>'.esc_html($r['active']).'</td><td><form method="post" style="display:inline">'.nexa_csrf_field().'<input type="hidden" name="id" value="'.(int)$r['id'].'"><input type="hidden" name="active" value="'.(((string)$r['active']==='1')?'0':'1').'"><button name="do" value="toggle" class="btn btn-xs btn-default">Toggle</button> <button name="do" value="del" class="btn btn-xs btn-danger">Delete</button></form></td></tr>';
    echo '</tbody></table>'; }

